    fn lower_main(source: &str) -> (crate::core::NodeId, MirProgram) {
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let callable = checked
            .callables()
            .values()
            .find(|callable| callable.owner.0.ends_with("main"))
            .expect("main callable");
        let function = lower_body(&callable.body).expect("MIR lowering");
        let owner = function.owner.clone();
        // The focused lower-body helper intentionally skips the production
        // CheckedProgram lowering pipeline, so install the checker-derived
        // TypeDesc catalog before running whole-program preflight.  A default
        // empty catalog treats every ordinary scalar as an unknown pointer;
        // that would falsely route a plain `match i32` into the ManagedAny
        // owner gate.
        let catalog = crate::core::mir::types::MirTypeCatalog::from_checked_program(&checked)
            .expect("MIR type catalog");
        let program =
            MirProgram::with_type_catalog(BTreeMap::from([(owner.clone(), function)]), catalog)
                .expect("MIR validation");
        (owner, program)
    }

    fn lower_program_with_main(source: &str) -> (crate::core::NodeId, MirProgram) {
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let owner = checked
            .callables()
            .values()
            .find(|callable| callable.owner.0.ends_with("main"))
            .map(|callable| callable.owner.clone())
            .expect("main callable");
        let program = MirProgram::new(lower_program(&checked).expect("MIR lowering"))
            .expect("MIR validation");
        (owner, program)
    }

    fn canonical_program_with_main(source: &str) -> (crate::core::NodeId, MirProgram) {
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let owner = checked
            .callables()
            .values()
            .find(|callable| callable.owner.0.ends_with("main"))
            .map(|callable| callable.owner.clone())
            .expect("main callable");
        let program = MirProgram::from_checked_program(&checked).expect("canonical MIR");
        (owner, program)
    }

    fn direct_v2_program_with_main(source: &str) -> (crate::core::NodeId, MirProgram) {
        let tokens = Lexer::new(source).tokenize().expect("lex");
        let file = Parser::new(tokens).parse_file().expect("parse");
        let checked = crate::core::check_program(&file).expect("check");
        let owner = checked
            .callables()
            .values()
            .find(|callable| callable.owner.0.ends_with("main"))
            .map(|callable| callable.owner.clone())
            .expect("main callable");
        let catalog = crate::core::mir::types::MirTypeCatalog::from_checked_program(&checked)
            .expect("checker-derived TypeDesc catalog");
        let functions =
            crate::core::mir::lower::lower_program_with_type_catalog(&checked, &catalog)
                .expect("checker-receipted V2 MIR lowering");
        let program = MirProgram::with_type_catalog(functions, catalog)
            .expect("checker-receipted V2 MIR validation");
        (owner, program)
    }

