    #[test]
    fn forged_ffi_symbol_declaration_shape_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            r#"
extern "C" { func foreign(value: i64) -> i64; }
func main() -> i64 {
    let narrow = foreign(7 as i32);
    let wide = foreign(8 as i64);
    narrow + wide
}
"#,
        );
        assert_eq!(program.ffi_calls().len(), 2);
        let main = program
            .functions()
            .get(&NodeId("function:main".into()))
            .expect("main MIR");
        let (second_id, second_argument) = program
            .ffi_calls()
            .iter()
            .find_map(|(id, receipt)| {
                let argument = receipt.arguments.first()?;
                let actual = main.values.get(argument)?;
                (actual.ty != receipt.parameter_types[0]).then(|| (id.clone(), argument.clone()))
            })
            .expect("mixed-width FFI receipt");
        let actual_type = main
            .values
            .get(&second_argument)
            .map(|value| value.ty.clone())
            .expect("second argument TypeDesc");

        let mut receipts = program.ffi_calls().clone();
        let forged_receipt = receipts.get_mut(&second_id).expect("second receipt");
        forged_receipt.parameter_types[0] = actual_type.clone();
        forged_receipt.parameter_conversions[0] =
            MirFfiAbiConversion::for_argument(program.type_catalog(), &actual_type, &actual_type)
                .expect("identity conversion");
        let mut forged = program;
        forged.replace_ffi_calls_for_test_only(receipts);

        let reference_error = MirReferenceInterpreter::new(&forged)
            .execute(&NodeId("function:main".into()), &[])
            .expect_err("reference must reject divergent FFI declaration shapes");
        assert!(reference_error
            .to_string()
            .contains("incompatible declaration TypeDescs"));

        let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged)
            .expect_err("bytecode must reject divergent FFI declaration shapes");
        assert!(bytecode_error
            .iter()
            .any(|error| error.message.contains("incompatible declaration TypeDescs")));

        let native_error = crate::codegen::mir::validate_mir_native(&forged)
            .expect_err("native validator must reject divergent FFI declaration shapes");
        assert!(native_error
            .iter()
            .any(|error| error.message.contains("incompatible declaration TypeDescs")));

        let capability_error = crate::verifier::validate_mir_capabilities(&forged)
            .expect_err("capability gate must reject divergent FFI declaration shapes");
        assert!(capability_error
            .iter()
            .any(|error| error.contains("incompatible declaration TypeDescs")));

        let verifier_error = crate::verifier::verify_mir(&forged, "forged-ffi-shape".into())
            .expect_err("direct verifier must reject divergent FFI declaration shapes");
        assert!(verifier_error.contains("incompatible declaration TypeDescs"));
    }

    #[test]
    fn forged_ffi_endpoint_metadata_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }",
        );
        let receipt = program.ffi_calls().values().next().expect("FFI receipt");
        let scalar_id = receipt
            .parameter_types
            .first()
            .expect("FFI parameter TypeDesc")
            .clone();
        let mut descriptor = program
            .type_catalog()
            .get(&scalar_id)
            .expect("scalar TypeDesc")
            .clone();
        descriptor.session_protocol = Some(scalar_id.clone());
        let mut catalog = program.type_catalog().clone();
        catalog.replace_for_test_only(scalar_id, descriptor);
        let forged = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            catalog,
            program.instances().clone(),
            program.transitions().clone(),
            program.ffi_calls().clone(),
        )
        .expect("MIR boundary retains a forged endpoint for consumer gates");

        let reference_error = MirReferenceInterpreter::new(&forged)
            .execute(&NodeId("function:main".into()), &[])
            .expect_err("reference must reject forged endpoint metadata");
        assert_eq!(
            reference_error.diagnostic_code(),
            Some(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
        );
        assert!(
            reference_error
                .to_string()
                .contains("complete scalar endpoint contract"),
            "{reference_error}"
        );

        let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged)
            .expect_err("bytecode must reject forged endpoint metadata");
        assert!(bytecode_error.iter().any(|error| {
            error.diagnostic_code()
                == Some(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && (error.message.contains("complete scalar endpoint contract")
                    || error.message.contains("complete Copy scalar shape"))
        }));

        let native_error = crate::codegen::mir::validate_mir_native(&forged)
            .expect_err("native must reject forged endpoint metadata");
        assert!(native_error.iter().any(|error| {
            error.code.as_deref() == Some(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && error.message.contains("complete scalar endpoint contract")
        }));

        let capability_error = crate::verifier::validate_mir_capabilities(&forged)
            .expect_err("verifier capability gate must reject forged endpoint metadata");
        assert!(capability_error.iter().any(|error| {
            error.contains(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && error.contains("complete scalar endpoint contract")
        }));

        let verifier_error = crate::verifier::verify_mir(&forged, "forged-ffi-endpoint".into())
            .expect_err("verifier must reject forged endpoint metadata");
        assert!(
            verifier_error.contains(crate::core::mir::MIR_FFI_DECLARATION_BOUNDARY_ERROR_CODE)
                && verifier_error.contains("complete scalar endpoint contract"),
            "{verifier_error}"
        );
    }

    #[test]
    fn forged_ffi_conversion_receipt_is_rejected_by_every_direct_consumer() {
        let (_, program) = canonical_program_with_main(
            "extern \"C\" { func foreign(value: i64) -> i32; } func main() -> i32 { foreign(1 as i64) }",
        );
        let receipt = program.ffi_calls().values().next().expect("FFI receipt");
        assert_eq!(receipt.parameter_conversions.len(), 1);
        assert!(receipt.result_conversion.is_some());

        for mutation in 0..2 {
            let mut receipts = program.ffi_calls().clone();
            let forged = receipts.values_mut().next().expect("FFI receipt");
            if mutation == 0 {
                forged.parameter_conversions[0] = MirFfiAbiConversion {
                    from: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 32,
                        signed: true,
                    },
                    to: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 64,
                        signed: true,
                    },
                };
            } else {
                forged.result_conversion = Some(MirFfiAbiConversion {
                    from: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 64,
                        signed: true,
                    },
                    to: crate::core::mir::types::MirAbiClass::Integer {
                        bits: 32,
                        signed: true,
                    },
                });
            }
            let mut forged_program = program.clone();
            forged_program.replace_ffi_calls_for_test_only(receipts);

            let reference_error = MirReferenceInterpreter::new(&forged_program)
                .execute(&NodeId("function:main".into()), &[])
                .expect_err("reference must reject forged conversion receipt");
            assert!(
                reference_error
                    .to_string()
                    .contains("conversion receipt disagrees")
                    || reference_error.to_string().contains("conversion from"),
                "{reference_error}"
            );

            let bytecode_error = crate::interp::bytecode::compile_mir_program(&forged_program)
                .expect_err("bytecode must reject forged conversion receipt");
            assert!(bytecode_error.iter().any(|error| {
                error.message.contains("conversion receipt disagrees")
                    || error.message.contains("conversion from")
            }));

            let native_error = crate::codegen::mir::validate_mir_native(&forged_program)
                .expect_err("native must reject forged conversion receipt");
            assert!(native_error.iter().any(|error| {
                error.message.contains("conversion receipt disagrees")
                    || error.message.contains("conversion from")
            }));

            let capability_error = crate::verifier::validate_mir_capabilities(&forged_program)
                .expect_err("verifier capability gate must reject forged conversion receipt");
            assert!(capability_error.iter().any(|error| {
                error.contains("conversion receipt disagrees") || error.contains("conversion from")
            }));

            let verifier_error =
                crate::verifier::verify_mir(&forged_program, "forged-ffi-conversion".into())
                    .expect_err("verifier must reject forged conversion receipt");
            assert!(
                verifier_error.contains("conversion receipt disagrees")
                    || verifier_error.contains("conversion from"),
                "{verifier_error}"
            );
        }
    }

    #[test]
    fn canonical_program_gate_rejects_orphaned_ffi_receipts() {
        let source = "extern \"C\" { func foreign(value: i64) -> i64; } func main() -> i64 { foreign(1 as i64) }";
        let (_, program) = canonical_program_with_main(source);
        let receipt = program
            .ffi_calls()
            .values()
            .next()
            .cloned()
            .expect("FFI receipt");
        let orphan_instruction =
            crate::core::mir::MirInstructionId::new("inst:call:orphan").expect("instruction id");
        let mut orphan = receipt;
        orphan.instruction = orphan_instruction.clone();
        let mut receipts = program.ffi_calls().clone();
        receipts.insert(orphan_instruction, orphan);
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("orphaned FFI receipts must fail before consumers");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("canonical FFI contract is orphaned from a MIR extern call")
            }),
            "{errors:?}"
        );

        let (_, program) = canonical_program_with_main(source);
        let forged_argument = super::MirValueId::new("value:forged-argument").expect("value id");
        let instruction_id = program
            .ffi_calls()
            .keys()
            .next()
            .cloned()
            .expect("FFI instruction");
        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .arguments = vec![forged_argument];
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI value identities must be declared by the caller MIR function");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("FFI contract argument 0 value identity is absent")
            }),
            "{errors:?}"
        );

        let (_, program) = canonical_program_with_main(source);
        let bool_type = program
            .type_catalog()
            .iter()
            .find_map(|(id, descriptor)| {
                matches!(descriptor.abi, crate::core::mir::types::MirAbiClass::Bool)
                    .then(|| id.clone())
            })
            .expect("bool TypeDesc");
        let instruction_id = program
            .ffi_calls()
            .keys()
            .next()
            .cloned()
            .expect("FFI instruction");
        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .parameter_types = vec![bool_type.clone()];
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI declaration and MIR argument TypeDescs must agree");
        assert!(
            errors.iter().any(|error| {
                error
                    .message
                    .contains("FFI declaration parameter 0 TypeDesc disagrees with MIR argument")
            }),
            "{errors:?}"
        );

        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .parameter_types
            .clear();
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI declaration parameter arity must be represented in the receipt");
        assert!(
            errors.iter().any(|error| {
                error.message.contains(
                    "extern call FFI declaration parameter TypeDesc count disagrees with MIR arguments",
                )
            }),
            "{errors:?}"
        );

        let mut receipts = program.ffi_calls().clone();
        receipts
            .get_mut(&instruction_id)
            .expect("FFI receipt")
            .result_type = bool_type;
        let errors = MirProgram::with_type_catalog_and_instances_and_transitions_and_ffi(
            program.functions().clone(),
            program.type_catalog().clone(),
            program.instances().clone(),
            program.transitions().clone(),
            receipts,
        )
        .expect_err("FFI declaration result TypeDesc must agree with MIR result");
        assert!(
            errors.iter().any(|error| {
                error.message.contains(
                    "extern call FFI declaration result TypeDesc disagrees with MIR result",
                )
            }),
            "{errors:?}"
        );
    }

